32	function getViewRect(seriesModel: PieSeriesModel, api: ExtensionAPI) {
33	    return layout.getLayoutRect(
34	        seriesModel.getBoxLayoutParams(), {
35	            width: api.getWidth(),
36	            height: api.getHeight()
