41	export function getBasicPieLayout(seriesModel: PieSeriesModel, api: ExtensionAPI):
42	    Pick<SectorShape, 'cx' | 'cy' | 'r' | 'r0'> {
43	    const viewRect = getViewRect(seriesModel, api);
44	
45	    // center can be string or number when coordinateSystem is specified
46	    let center = seriesModel.get('center');
47	    let radius = seriesModel.get('radius');
48	
49	    if (!zrUtil.isArray(radius)) {
50	        radius = [0, radius];
51	    }
52	    const width = parsePercent(viewRect.width, api.getWidth());
53	    const height = parsePercent(viewRect.height, api.getHeight());
54	    const size = Math.min(width, height);
55	    const r0 = parsePercent(radius[0], size / 2);
56	    const r = parsePercent(radius[1], size / 2);
57	
58	    let cx: number;
59	    let cy: number;
60	    const coordSys = seriesModel.coordinateSystem;
61	    if (coordSys) {
62	        // percentage is not allowed when coordinate system is specified
63	        const point = coordSys.dataToPoint(center);
64	        cx = point[0] || 0;
65	        cy = point[1] || 0;
66	    }
67	    else {
68	        if (!zrUtil.isArray(center)) {
69	            center = [center, center];
70	        }
71	        cx = parsePercent(center[0], width) + viewRect.x;
72	        cy = parsePercent(center[1], height) + viewRect.y;
73	    }
74	
75	    return {
76	        cx,
77	        cy,
78	        r0,
79	        r
80	    };
81	}
