83	export default function pieLayout(
84	    seriesType: 'pie',
85	    ecModel: GlobalModel,
86	    api: ExtensionAPI
87	) {
88	    ecModel.eachSeriesByType(seriesType, function (seriesModel: PieSeriesModel) {
89	        const data = seriesModel.getData();
90	        const valueDim = data.mapDimension('value');
91	        const viewRect = getViewRect(seriesModel, api);
92	
93	        const { cx, cy, r, r0 } = getBasicPieLayout(seriesModel, api);
94	
95	        let startAngle = -seriesModel.get('startAngle') * RADIAN;
96	        let endAngle = seriesModel.get('endAngle');
97	        const padAngle = seriesModel.get('padAngle') * RADIAN;
98	
99	        endAngle = endAngle === 'auto' ? startAngle - PI2 : -endAngle * RADIAN;
100	
101	        const minAngle = seriesModel.get('minAngle') * RADIAN;
102	
103	        const minAndPadAngle = minAngle + padAngle;
104	
105	        let validDataCount = 0;
106	        data.each(valueDim, function (value: number) {
107	            !isNaN(value) && validDataCount++;
108	        });
109	
110	        const sum = data.getSum(valueDim);
111	        // Sum may be 0
112	        let unitRadian = Math.PI / (sum || validDataCount) * 2;
113	
114	        const clockwise = seriesModel.get('clockwise');
115	
116	        const roseType = seriesModel.get('roseType');
117	        const stillShowZeroSum = seriesModel.get('stillShowZeroSum');
118	
119	        // [0...max]
120	        const extent = data.getDataExtent(valueDim);
121	        extent[0] = 0;
122	
123	        const dir = clockwise ? 1 : -1;
124	        const angles = [startAngle, endAngle];
125	        const halfPadAngle = dir * padAngle / 2;
126	        normalizeArcAngles(angles, !clockwise);
127	
128	        [startAngle, endAngle] = angles;
129	
130	        const angleRange = Math.abs(endAngle - startAngle);
131	
132	        // In the case some sector angle is smaller than minAngle
133	        let restAngle = angleRange;
134	        let valueSumLargerThanMinAngle = 0;
135	
136	        let currentAngle = startAngle;
137	
138	        data.setLayout({ viewRect, r });
139	
140	        data.each(valueDim, function (value: number, idx: number) {
141	            let angle;
142	            if (isNaN(value)) {
143	                data.setItemLayout(idx, {
144	                    angle: NaN,
145	                    startAngle: NaN,
146	                    endAngle: NaN,
147	                    clockwise: clockwise,
148	                    cx: cx,
149	                    cy: cy,
150	                    r0: r0,
151	                    r: roseType
152	                        ? NaN
153	                        : r
154	                });
155	                return;
156	            }
157	
158	            // FIXME 兼容 2.0 但是 roseType 是 area 的时候才是这样？
159	            if (roseType !== 'area') {
160	                angle = (sum === 0 && stillShowZeroSum)
161	                    ? unitRadian : (value * unitRadian);
162	            }
163	            else {
164	                angle = angleRange / validDataCount;
165	            }
166	
167	
168	            if (angle < minAndPadAngle) {
169	                angle = minAndPadAngle;
170	                restAngle -= minAndPadAngle;
171	            }
172	            else {
173	                valueSumLargerThanMinAngle += value;
174	            }
175	
176	            const endAngle = currentAngle + dir * angle;
177	
178	            // calculate display angle
179	            let actualStartAngle = 0;
180	            let actualEndAngle = 0;
181	
182	            if (padAngle > angle) {
183	                actualStartAngle = currentAngle + dir * angle / 2;
184	                actualEndAngle = actualStartAngle;
185	            }
186	            else {
187	                actualStartAngle = currentAngle + halfPadAngle;
188	                actualEndAngle = endAngle - halfPadAngle;
189	            }
190	
191	            data.setItemLayout(idx, {
192	                angle: angle,
193	                startAngle: actualStartAngle,
194	                endAngle: actualEndAngle,
195	                clockwise: clockwise,
196	                cx: cx,
197	                cy: cy,
198	                r0: r0,
199	                r: roseType
200	                    ? linearMap(value, extent, [r0, r])
201	                    : r
202	            });
203	
204	            currentAngle = endAngle;
205	        });
206	
207	        // Some sector is constrained by minAngle and padAngle
208	        // Rest sectors needs recalculate angle
209	        if (restAngle < PI2 && validDataCount) {
210	            // Average the angle if rest angle is not enough after all angles is
211	            // Constrained by minAngle and padAngle
212	            if (restAngle <= 1e-3) {
213	                const angle = angleRange / validDataCount;
214	                data.each(valueDim, function (value: number, idx: number) {
215	                    if (!isNaN(value)) {
216	                        const layout = data.getItemLayout(idx);
217	                        layout.angle = angle;
218	
219	                        let actualStartAngle = 0;
220	                        let actualEndAngle = 0;
221	
222	                        if (angle < padAngle) {
223	                            actualStartAngle = startAngle + dir * (idx + 1 / 2) * angle;
224	                            actualEndAngle = actualStartAngle;
225	                        }
226	                        else {
227	                             actualStartAngle = startAngle + dir * idx * angle + halfPadAngle;
228	                             actualEndAngle = startAngle + dir * (idx + 1) * angle - halfPadAngle;
229	                        }
230	
231	                        layout.startAngle = actualStartAngle;
232	                        layout.endAngle = actualEndAngle;
233	                    }
234	                });
235	            }
236	            else {
237	                unitRadian = restAngle / valueSumLargerThanMinAngle;
238	                currentAngle = startAngle;
239	                data.each(valueDim, function (value: number, idx: number) {
240	                    if (!isNaN(value)) {
241	                        const layout = data.getItemLayout(idx);
242	                        const angle = layout.angle === minAndPadAngle
243	                            ? minAndPadAngle : value * unitRadian;
244	
245	                        let actualStartAngle = 0;
246	                        let actualEndAngle = 0;
247	
248	                        if (angle < padAngle) {
249	                            actualStartAngle = currentAngle + dir * angle / 2;
250	                            actualEndAngle = actualStartAngle;
251	                        }
252	                        else {
253	                            actualStartAngle = currentAngle + halfPadAngle;
254	                            actualEndAngle = currentAngle + dir * angle - halfPadAngle;
255	                        }
256	
257	                        layout.startAngle = actualStartAngle;
258	                        layout.endAngle = actualEndAngle;
259	                        currentAngle += dir * angle;
260	                    }
261	                });
262	            }
263	        }
264	    });
265	}
