import { EChartsType } from '@/src/echarts';
import { createChart, getGraphicElements } from '../../../core/utHelper';
import Sector from 'zrender/src/graphic/shape/Sector';
import Element from 'zrender/src/Element';
import { filter } from 'zrender/src/core/util';

const RADIAN = Math.PI / 180;

function getEmptyCircleSectors(chart: EChartsType): Sector[] {
    const els = getGraphicElements(chart, 'series', 0);
    return filter(els, (el: Element) => el.type === 'sector') as Sector[];
}

describe('pie_empty_circle', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('should apply startAngle and endAngle on the empty circle', function () {
        chart.setOption({
            series: [{
                type: 'pie',
                startAngle: 180,
                endAngle: 30,
                data: []
            }]
        });

        const sectors = getEmptyCircleSectors(chart);
        expect(sectors.length).toEqual(1);
        expect(sectors[0].shape.startAngle).toBeCloseTo(-180 * RADIAN, 6);
        expect(sectors[0].shape.endAngle).toBeCloseTo(-30 * RADIAN, 6);
    });

    it('should keep a full circle when endAngle is auto', function () {
        chart.setOption({
            series: [{
                type: 'pie',
                startAngle: 90,
                data: []
            }]
        });

        const sectors = getEmptyCircleSectors(chart);
        expect(sectors.length).toEqual(1);
        const shape = sectors[0].shape;
        expect(shape.startAngle).toBeCloseTo(-90 * RADIAN, 6);
        expect(Math.abs(shape.endAngle - shape.startAngle)).toBeCloseTo(Math.PI * 2, 6);
    });

    it('empty circle should share the geometry of a non-empty pie', function () {
        const option = {
            series: [{
                type: 'pie',
                startAngle: 210,
                endAngle: 330,
                data: [{ value: 1 }]
            }]
        };
        chart.setOption(option);
        const dataLayout = (chart as any).getModel()
            .getSeriesByIndex(0).getData().getItemLayout(0);

        chart.setOption({
            series: [{
                type: 'pie',
                startAngle: 210,
                endAngle: 330,
                data: []
            }]
        }, true);

        const sectors = getEmptyCircleSectors(chart);
        expect(sectors.length).toEqual(1);
        expect(sectors[0].shape.startAngle).toBeCloseTo(dataLayout.startAngle, 6);
        expect(sectors[0].shape.endAngle).toBeCloseTo(dataLayout.endAngle, 6);
    });
});

