import { createChart } from '../../../core/utHelper';
import { Sector } from '../../../../../src/util/graphic';
import BoundingRect from 'zrender/src/core/BoundingRect';

interface Info {
    idx: number; name: string; hidden: boolean; rect: BoundingRect; side: string; x: number; y: number;
}

function collect(chart: any) {
    const data = chart.getModel().getSeriesByIndex(0).getData();
    const cx = data.getItemLayout(0).cx;
    const infos: Info[] = [];
    data.each(function (idx: number) {
        const sector = data.getItemGraphicEl(idx) as Sector;
        const label = sector.getTextContent();
        const rect = label.getBoundingRect().clone();
        rect.applyTransform(label.getComputedTransform());
        const margin = ((label.style.margin as number) || 0) + 2.1;
        rect.y -= margin / 2;
        rect.height += margin;
        infos.push({
            idx, name: data.getName(idx), hidden: !!label.ignore, rect,
            side: label.x < cx ? 'L' : 'R', x: label.x, y: label.y
        });
    });
    return infos;
}

function overlapPairs(infos: Info[]) {
    const out: string[] = [];
    for (let i = 0; i < infos.length; i++) {
        for (let j = i + 1; j < infos.length; j++) {
            if (infos[i].side !== infos[j].side) {
                continue;
            }
            if (infos[i].rect.intersect(infos[j].rect)) {
                out.push(`${infos[i].idx}(${infos[i].hidden ? 'hidden' : 'shown'})~${infos[j].idx}(${infos[j].hidden ? 'hidden' : 'shown'})`);
            }
        }
    }
    return out;
}

describe('scratch5', function () {
    it('same-side overlap search', function () {
        const results: string[] = [];
        const counts = [4, 6, 8, 10, 12, 16];
        const radii: any[] = ['55%', '75%', ['40%', '70%']];
        const aligns = ['none', 'edge', 'labelLine'];
        const overflows = [null, 'break', 'breakAll', 'truncate'];
        const sizes = [[500, 400], [600, 400], [400, 400], [800, 500]];
        for (const [w, h] of sizes) {
            for (const n of counts) {
                for (const radius of radii) {
                    for (const alignTo of aligns) {
                        for (const overflow of overflows) {
                            const chart = createChart({width: w, height: h});
                            const data = [];
                            for (let i = 0; i < n; i++) {
                                data.push({name: 'Item ' + i + ' ' + 'word'.repeat(1 + i % 5), value: 5 + (i * 7) % 13});
                            }
                            chart.setOption({
                                series: [{
                                    type: 'pie', radius,
                                    label: overflow ? {alignTo, overflow} : {alignTo},
                                    data
                                }]
                            });
                            const infos = collect(chart);
                            const pairs = overlapPairs(infos);
                            const hidden = infos.filter(i => i.hidden).map(i => i.idx);
                            if (pairs.length || hidden.length) {
                                results.push(`${w}x${h} n=${n} r=${JSON.stringify(radius)} alignTo=${alignTo} overflow=${overflow} hidden=[${hidden}] pairs=${pairs.join(',')}`);
                            }
                            chart.dispose();
                        }
                    }
                }
            }
        }
        console.log('CASES:', results.length);
        console.log(results.slice(0, 30).join('\n'));
    });
});
