// Use ellipse implicit function to calculate x
// `dy` may be larger than `rB` when the labels are dense and have
// been shifted out of the ellipse on the y axis. In that case the
// radicand would be negative, which makes `dx` (and thus the label
// position) NaN and the label be dropped afterwards. Clamp it to
// keep the label on the ellipse (x is not moved outwards then).
const dx = Math.sqrt(Math.max(1 - dy * dy / rB2, 0) * rA2);

