import { createChart } from '../../../core/utHelper';
import { Sector } from '../../../../../src/util/graphic';
import { platformApi } from 'zrender/src/core/platform';

platformApi.measureText = function (text: string, font?: string) {
    const res = /(\d+)px/.exec(font || '');
    const fontSize = (res && +res[1]) || 12;
    return { width: (text || '').length * fontSize * 0.55 };
};

describe('scratch8', function () {
    it('detail after fix', function () {
        const chart = createChart({width: 500, height: 400});
        const data: any[] = [{name: 'Dominant', value: 1000}];
        for (let i = 0; i < 32; i++) {
            data.push({name: 'Tiny ' + i + ' ' + 'ab'.repeat(1 + i % 4), value: 1});
        }
        chart.setOption({ series: [{type: 'pie', radius: '50%', startAngle: 0, data}] });
        const sdata = (chart as any).getModel().getSeriesByIndex(0).getData();
        const rows: string[] = [];
        sdata.each(function (idx: number) {
            const sector = sdata.getItemGraphicEl(idx) as Sector;
            const label = sector.getTextContent();
            const rect = label.getBoundingRect().clone();
            rect.applyTransform(label.getComputedTransform());
            rows.push(`${idx} ign=${label.ignore} x=${Math.round(label.x)} y=${Math.round(label.y)} `
                + `rect=[${Math.round(rect.x)},${Math.round(rect.y)},${Math.round(rect.width)},${Math.round(rect.height)}] align=${label.style.align}`);
        });
        console.log(rows.join('\n'));
        chart.dispose();
    });
});
