        const results: string[] = [];
        for (const n of [16, 24, 32, 40]) {
            for (const big of [200, 1000]) {
                for (const startAngle of [0, 90, 45, 180]) {
                    const chart = createChart({width: 500, height: 400});
                    const data: any[] = [{name: 'Dominant', value: big}];
                    for (let i = 0; i < n; i++) {
                        data.push({name: 'Tiny ' + i, value: 1});
                    }
                    chart.setOption({ series: [{type: 'pie', radius: '50%', startAngle, data}] });
                    const sdata = (chart as any).getModel().getSeriesByIndex(0).getData();
                    const bad: string[] = [];
                    sdata.each(function (idx: number) {
                        const label = (sdata.getItemGraphicEl(idx) as Sector).getTextContent();
                        if (isNaN(label.x) || isNaN(label.y) || label.ignore) {
                            bad.push(idx + (isNaN(label.x) ? ':NaNx' : '') + (label.ignore ? ':ign' : ''));
