import { EChartsType } from '@/src/echarts';
import { createChart } from '../../../core/utHelper';
import { Sector } from '@/src/util/graphic';
import SeriesData from '@/src/data/SeriesData';

function getSeriesData(chart: EChartsType): SeriesData {
    return (chart as any).getModel().getSeriesByIndex(0).getData();
}

interface LabelState {
    dataIndex: number
    name: string
    x: number
    y: number
    ignore: boolean
}

function getLabelStates(chart: EChartsType): LabelState[] {
    const data = getSeriesData(chart);
    const list: LabelState[] = [];
    data.each(function (dataIndex: number) {
        const sector = data.getItemGraphicEl(dataIndex) as Sector;
        const label = sector.getTextContent();
        list.push({
            dataIndex,
            name: data.getName(dataIndex),
            x: label.x,
            y: label.y,
            ignore: !!label.ignore
        });
    });
    return list;
}

describe('pie_labelLayout', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 500, height: 400 });
    });

    afterEach(function () {
        chart.dispose();
    });

    it('should not drop labels that can be laid out when labels are dense', function () {
        // One dominant sector plus many tiny sectors makes all the tiny labels
        // gather on a small arc, so they are shifted far away on the y axis by
        // `avoidLabelOverlap`.
        const data: {name: string, value: number}[] = [{ name: 'Dominant', value: 1000 }];
        for (let i = 0; i < 40; i++) {
            data.push({ name: 'Tiny ' + i, value: 1 });
        }

        chart.setOption({
            series: [{
                type: 'pie',
                radius: '50%',
                startAngle: 180,
                data
            }]
        });

        const labels = getLabelStates(chart);
        expect(labels.length).toEqual(41);

        const invalid = labels.filter(item => isNaN(item.x) || isNaN(item.y));
        expect(invalid.map(item => item.name)).toEqual([]);

        const hidden = labels.filter(item => item.ignore);
        expect(hidden.map(item => item.name)).toEqual([]);
    });

    it('should keep the labels of both sides separated on x axis', function () {
        const data: {name: string, value: number}[] = [{ name: 'Dominant', value: 1000 }];
        for (let i = 0; i < 40; i++) {
            data.push({ name: 'Tiny ' + i, value: 1 });
        }

        chart.setOption({
            series: [{
                type: 'pie',
                radius: '50%',
                startAngle: 180,
                data
            }]
        });

        const cx = getSeriesData(chart).getItemLayout(0).cx;
        const labels = getLabelStates(chart);
        // The labels laid out on the ellipse curve should never be moved
        // across the center of the pie.
        for (let i = 0; i < labels.length; i++) {
            expect(Math.abs(labels[i].x - cx)).toBeGreaterThan(0);
        }
    });
});
